const fs = require('fs');
const path = require('path');

const files = {
  'prisma/schema.prisma': `generator client {
    provider = "prisma-client-js"
    }

    datasource db {
      provider = "postgresql"
        url      = env("DATABASE_URL")
        }

        model User {
          id            String    @id @default(cuid())
            name          String?
              phone         String?   @unique
                password      String?
                  role          String    @default("CUSTOMER")
                    createdAt     DateTime  @default(now())
                      ordersCreated Order[]   @relation("CustomerOrders")
                        ordersTaken   Order[]   @relation("DriverOrders")
                        }

                        model Order {
                          id             String    @id @default(cuid())
                            status         String    @default("PENDING")
                              pickupAddress  String
                                dropoffAddress String
                                  totalAmount    Float
                                    customerId     String
                                      customer       User      @relation("CustomerOrders", fields: [customerId], references: [id])
                                        driverId       String?
                                          driver         User?     @relation("DriverOrders", fields: [driverId], references: [id])
                                            createdAt      DateTime  @default(now())
                                              updatedAt      DateTime  @updatedAt
                                              }`,

                                                'prisma.config.ts': `import "dotenv/config";
                                                import { definePrismaConfig } from "prisma/config";
                                                import { defineConfig as ormConfig } from "@prisma/orm-postgres/config";

                                                export default definePrismaConfig({
                                                  orm: ormConfig({
                                                      contract: "./prisma/schema.prisma",
                                                          db: {
                                                                connection: process.env["DATABASE_URL"]!,
                                                                    },
                                                                      }),
                                                                      });`,

                                                                        'lib/prisma.ts': `import { PrismaClient } from '@prisma/client'
                                                                        const globalForPrisma = global as unknown as { prisma: PrismaClient }
                                                                        export const prisma = globalForPrisma.prisma || new PrismaClient()
                                                                        if (process.env.NODE_ENV !== 'production') globalForPrisma.prisma = prisma`,

                                                                          'app/page.tsx': `"use client";
                                                                          import { useState } from "react";
                                                                          import { MapPin, Navigation, Package, CheckCircle } from "lucide-react";

                                                                          export default function CustomerHome() {
                                                                            const [loading, setLoading] = useState(false);
                                                                              const [success, setSuccess] = useState(false);
                                                                                const [formData, setFormData] = useState({ pickupAddress: "", dropoffAddress: "", totalAmount: "" });

                                                                                  const handleSubmit = async (e: React.FormEvent) => {
                                                                                      e.preventDefault();
                                                                                          setLoading(true);
                                                                                              try {
                                                                                                    const res = await fetch("/api/orders", {
                                                                                                            method: "POST",
                                                                                                                    headers: { "Content-Type": "application/json" },
                                                                                                                            body: JSON.stringify({ ...formData, totalAmount: parseFloat(formData.totalAmount) }),
                                                                                                                                  });
                                                                                                                                        if (res.ok) {
                                                                                                                                                setSuccess(true);
                                                                                                                                                        setFormData({ pickupAddress: "", dropoffAddress: "", totalAmount: "" });
                                                                                                                                                                setTimeout(() => setSuccess(false), 5000);
                                                                                                                                                                      }
                                                                                                                                                                          } catch (error) { console.error(error); } finally { setLoading(false); }
                                                                                                                                                                            };

                                                                                                                                                                              return (
                                                                                                                                                                                  <div className="min-h-screen bg-slate-50 p-4 flex items-center justify-center" dir="rtl">
                                                                                                                                                                                        <div className="bg-white p-8 rounded-2xl shadow-xl w-full max-w-md">
                                                                                                                                                                                                <div className="text-center mb-8">
                                                                                                                                                                                                          <Package className="w-12 h-12 text-blue-600 mx-auto mb-4" />
                                                                                                                                                                                                                    <h1 className="text-2xl font-bold text-gray-800">اطلب توصيلك</h1>
                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                    {success && <div className="bg-green-50 text-green-700 p-4 rounded-lg mb-6">تم إرسال طلبك بنجاح!</div>}
                                                                                                                                                                                                                                            <form onSubmit={handleSubmit} className="space-y-5">
                                                                                                                                                                                                                                                      <div className="relative">
                                                                                                                                                                                                                                                                  <MapPin className="absolute right-3 top-3 w-5 h-5 text-green-500" />
                                                                                                                                                                                                                                                                              <input type="text" required value={formData.pickupAddress} onChange={(e) => setFormData({ ...formData, pickupAddress: e.target.value })} className="w-full pl-3 pr-10 py-3 border rounded-lg" placeholder="من (عنوان الاستلام)" />
                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                  <div className="relative">
                                                                                                                                                                                                                                                                                                              <Navigation className="absolute right-3 top-3 w-5 h-5 text-red-500" />
                                                                                                                                                                                                                                                                                                                          <input type="text" required value={formData.dropoffAddress} onChange={(e) => setFormData({ ...formData, dropoffAddress: e.target.value })} className="w-full pl-3 pr-10 py-3 border rounded-lg" placeholder="إلى (عنوان التوصيل)" />
                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                              <input type="number" required value={formData.totalAmount} onChange={(e) => setFormData({ ...formData, totalAmount: e.target.value })} className="w-full px-3 py-3 border rounded-lg" placeholder="سعر التوصيل (ل.س)" />
                                                                                                                                                                                                                                                                                                                                                        <button type="submit" disabled={loading} className="w-full bg-blue-600 text-white font-bold py-3 rounded-lg">
                                                                                                                                                                                                                                                                                                                                                                    {loading ? "جاري الإرسال..." : "تأكيد الطلب"}
                                                                                                                                                                                                                                                                                                                                                                              </button>
                                                                                                                                                                                                                                                                                                                                                                                      </form>
                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                  );
                                                                                                                                                                                                                                                                                                                                                                                                  }`,

                                                                                                                                                                                                                                                                                                                                                                                                    'app/driver/page.tsx': `"use client";
                                                                                                                                                                                                                                                                                                                                                                                                    import { useState, useEffect } from "react";
                                                                                                                                                                                                                                                                                                                                                                                                    import { MapPin, Navigation, CheckCircle } from "lucide-react";

                                                                                                                                                                                                                                                                                                                                                                                                    export default function DriverDashboard() {
                                                                                                                                                                                                                                                                                                                                                                                                      const [orders, setOrders] = useState([]);
                                                                                                                                                                                                                                                                                                                                                                                                        const [loading, setLoading] = useState(true);

                                                                                                                                                                                                                                                                                                                                                                                                          const fetchOrders = async () => {
                                                                                                                                                                                                                                                                                                                                                                                                              const res = await fetch("/api/orders/pending");
                                                                                                                                                                                                                                                                                                                                                                                                                  const data = await res.json();
                                                                                                                                                                                                                                                                                                                                                                                                                      setOrders(data);
                                                                                                                                                                                                                                                                                                                                                                                                                          setLoading(false);
                                                                                                                                                                                                                                                                                                                                                                                                                            };

                                                                                                                                                                                                                                                                                                                                                                                                                              useEffect(() => {
                                                                                                                                                                                                                                                                                                                                                                                                                                  fetchOrders();
                                                                                                                                                                                                                                                                                                                                                                                                                                      const interval = setInterval(fetchOrders, 5000);
                                                                                                                                                                                                                                                                                                                                                                                                                                          return () => clearInterval(interval);
                                                                                                                                                                                                                                                                                                                                                                                                                                            }, []);

                                                                                                                                                                                                                                                                                                                                                                                                                                              const acceptOrder = async (id: string) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                  const res = await fetch("/api/orders/" + id + "/accept", { method: "POST" });
                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (res.ok) { alert("تم القبول!"); fetchOrders(); }
                                                                                                                                                                                                                                                                                                                                                                                                                                                        };

                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (loading) return <div className="p-8 text-center text-white bg-slate-900 min-h-screen">جاري التحميل...</div>;

                                                                                                                                                                                                                                                                                                                                                                                                                                                            return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div className="min-h-screen bg-slate-900 p-4 text-white" dir="rtl">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <h1 className="text-xl font-bold mb-6">تطبيق المندوب 🛵</h1>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div className="space-y-4">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {orders.length === 0 ? <p className="text-center text-slate-400">لا توجد طلبات...</p> : orders.map((o: any) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div key={o.id} className="bg-slate-800 p-5 rounded-xl border border-slate-700">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div className="flex justify-between mb-4">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <span className="bg-yellow-500/20 text-yellow-500 text-xs px-2 py-1 rounded">طلب جديد</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <span className="text-green-400 font-bold">{o.totalAmount} ل.س</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <p className="text-sm mb-2"><span className="text-gray-400">من:</span> {o.pickupAddress}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <p className="text-sm mb-4"><span className="text-gray-400">إلى:</span> {o.dropoffAddress}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <button onClick={() => acceptOrder(o.id)} className="w-full bg-blue-600 py-2 rounded-lg font-bold">قبول الطلب</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }`,

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      'app/api/orders/route.ts': `import { NextResponse } from "next/server";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      import { prisma } from "@/lib/prisma";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      export async function POST(req: Request) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const body = await req.json();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                let customer = await prisma.user.findFirst({ where: { role: "CUSTOMER" } });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (!customer) customer = await prisma.user.create({ data: { name: "عميل", role: "CUSTOMER" } });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const order = await prisma.order.create({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              data: { pickupAddress: body.pickupAddress, dropoffAddress: body.dropoffAddress, totalAmount: body.totalAmount, customerId: customer.id, status: "PENDING" },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return NextResponse.json(order, { status: 201 });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        } catch (error) { return NextResponse.json({ error: "فشل" }, { status: 500 }); }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }`,

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          'app/api/orders/pending/route.ts': `import { NextResponse } from "next/server";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          import { prisma } from "@/lib/prisma";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          export async function GET() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const orders = await prisma.order.findMany({ where: { status: "PENDING" }, orderBy: { createdAt: "desc" } });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return NextResponse.json(orders);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      } catch (error) { return NextResponse.json({ error: "فشل" }, { status: 500 }); }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }`,

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        'app/api/orders/[id]/accept/route.ts': `import { NextResponse } from "next/server";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        import { prisma } from "@/lib/prisma";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        export async function POST(req: Request, { params }: { params: Promise<{ id: string }> }) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const { id } = await params;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const updatedOrder = await prisma.order.update({ where: { id: id }, data: { status: "ACCEPTED" } });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return NextResponse.json(updatedOrder);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        } catch (error) { return NextResponse.json({ error: "فشل" }, { status: 500 }); }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }`
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Object.entries(files).forEach(([filePath, content]) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const dir = path.dirname(filePath);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            fs.mkdirSync(dir, { recursive: true });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              fs.writeFileSync(filePath, content);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                console.log('✅ Created: ' + filePath);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                console.log('🎉 All folders and files created successfully!');